 static IEnumerable<TextBlock> AllText(DependencyObject obj){if(obj is TextBlock)yield return (TextBlock)obj;for(int i=0;i<VisualTreeHelper.GetChildrenCount(obj);i++)foreach(var t in AllText(VisualTreeHelper.GetChild(obj,i)))yield return t;}
 static IEnumerable<Button> AllButtons(DependencyObject obj){if(obj is Button)yield return (Button)obj;for(int i=0;i<VisualTreeHelper.GetChildrenCount(obj);i++)foreach(var b in AllButtons(VisualTreeHelper.GetChild(obj,i)))yield return b;}
 static void CheckHit(CodeEditor editor,Rect a,Rect b,int i){if(editor.Input.Hit(new Point(a.X+(b.X-a.X)*.2,a.Y+a.Height*.5))!=i)throw new Exception("Cursor mismatch at "+i);}
